```typescript
/**
 * Broadcast a message to all connected clients EXCEPT the sender.
 * Used for user-query/steer echo so the sending client (which already has
 * a local optimistic bubble) doesn't get a duplicate.
 */
private broadcastExcept(
  sender: WebSocket,
  type: string,
  content: string,
  label?: string,
  detail?: string,
): void {
  const cleanContent = stripAnsi(content);
  const cleanDetail = detail ? stripAnsi(detail) : detail;
  const timestamp = Date.now();
  const payload = JSON.stringify({ type, content: cleanContent, label, timestamp, detail: cleanDetail || undefined });
  for (const ws of this.clients) {
    if (ws === sender) continue;
    if (ws.readyState === WebSocket.OPEN) {
      try { ws.send(payload); } catch { /* ignore */ }
    }
  }
}
```

