**Fix #2: sleep() listener (~line 206-223)**

BEFORE:
```ts
export function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) { reject(new StreamAbortedError()); return; }
    const timeoutId = setTimeout(resolve, ms);
    if (signal) {
      const onAbort = () => { clearTimeout(timeoutId); reject(new StreamAbortedError()); };
      signal.addEventListener('abort', onAbort, { once: true });
    }
  });
}
```

AFTER — remove the listener in the `setTimeout` resolve callback (the normal path):
```ts
export function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) { reject(new StreamAbortedError()); return; }
    const onAbort = () => { clearTimeout(timeoutId); reject(new StreamAbortedError()); };
    const timeoutId = setTimeout(() => {
      if (signal) signal.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    if (signal) signal.addEventListener('abort', onAbort, { once: true });
  });
}
```

Key: declare `onAbort` before `timeoutId` so the `setTimeout` callback can reference it. The `onAbort` closure already calls `clearTimeout(timeoutId)`, and `{ once: true }` auto-removes it on the abort path — so we only need to add `removeEventListener` to the normal `setTimeout` resolve path.

