  fs.mkdirSync(path.join(PROJECT_TMP, '.mycc', 'sessions'), { recursive: true });
  const id = `nonmonotonic-${Date.now()}`;
  makeEmptySession(PROJECT_TMP, id, 30); // 30 min old
  // Recent beat 10s ago, but a STALE beat (10 min ago) sits AFTER it in the array.
  // .pop() would return the 10-min-old beat → judged dead → deleted (the bug).
