**AFTER:**
```ts
export async function structuredChat(
  messages: { role: string; content: string }[],
  _format: object,
  options?: { signal?: AbortSignal; timeoutMs?: number; maxRetries?: number },
): Promise<ChatResponse> {
  const url = `${getHost()}/chat/completions`;
  const apiKey = getApiKey();
  const timeoutMs = options?.timeoutMs ?? 60000;
  const maxRetries = options?.maxRetries ?? 2;

  let lastError: Error | null = null;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    // Combine caller's signal with a timeout signal
    const signals: AbortSignal[] = [AbortSignal.timeout(timeoutMs)];
    if (options?.signal) signals.push(options.signal);
    const combinedSignal = AbortSignal.any(signals);

    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${apiKey}`,
        },
        body: JSON.stringify({
          model: MODEL,
          messages,
          response_format: { type: 'json_object' },
          stream: false,
        }),
        signal: combinedSignal,
      });

      if (!response.ok) {
        const text = await response.text().catch(() => '');
        throw new Error(`DeepSeek API error ${response.status}: ${text.slice(0, 500)}`);
      }

      const data = await response.json();
      const choice = data.choices?.[0];
      return {
        model: data.model || MODEL,
        created_at: new Date(),
        message: { role: 'assistant' as const, content: choice?.message?.content || '' },
        done: true,
        done_reason: choice?.finish_reason || 'stop',
        total_duration: 0, load_duration: 0,
        prompt_eval_count: data.usage?.prompt_tokens || 0,
        prompt_eval_duration: 0,
        eval_count: data.usage?.completion_tokens || 0,
        eval_duration: 0,
      };
    } catch (err) {
      lastError = err instanceof Error ? err : new Error(String(err));
      // Don't retry on caller abort
      if (options?.signal?.aborted) throw lastError;
      // Don't retry on non-transient errors (4xx)
      if (err instanceof Error && /DeepSeek API error 4\d\d/.test(err.message)) throw err;
      if (attempt < maxRetries) {
        await new Promise(r => setTimeout(r, 1000 * (attempt + 1)));
      }
    }
  }
  throw lastError || new Error('structuredChat: all retries exhausted');
}
```

**Caller update:** `src/hook/conditions.ts` `compile()` calls `structuredChat` — update the call to pass `{ signal: options?.signal }` if the compile method receives a signal, or at minimum rely on the built-in timeout. The `structuredChat` import in `src/engine/chat-provider.ts` (the re-export shim) must also accept the new `options` parameter.

