**AFTER:**
```ts
  let verboseWriteFailed = false;
  const writeChunk = (chunk: unknown): boolean => {
    try {
      if (typeof chunk === 'string' || Buffer.isBuffer(chunk)) {
        stream.write(chunk);
      } else {
        stream.write(String(chunk));
      }
    } catch (err) {
