#### Step 2: Add a safety gate function (`src/loop/states/tool.ts`)

```typescript
/**
 * Check if all non-blocked calls in the hook result are parallel-safe.
 * If any call is not parallel-safe, fall back to sequential execution.
 */
function canParallelize(calls: AugmentedToolCall[], blockedCalls: Map<string, string>): boolean {
  for (const call of calls) {
    if (blockedCalls.has(call.id)) continue; // blocked calls don't execute
    if (!PARALLEL_SAFE_TOOLS.has(call.function.name)) return false;
  }
  // Also require at least 2 executable calls (1 call = no parallelism benefit)
  const executableCount = calls.filter(c => !blockedCalls.has(c.id)).length;
  return executableCount >= 2;
}
```

