```typescript
async function handleToolParallel(env, turn, chat): Promise<HandlerResult> {
  const { triologue, ctx, sequence } = env;
  const hookResult = chat.hookResult;

  // 1. Start all non-blocked tools concurrently
  const executionMap = new Map<string, Promise<{ output: string; error?: Error }>>();
  for (const toolCall of hookResult.calls) {
    if (hookResult.blockedCalls.has(toolCall.id)) continue; // skip blocked
    const toolName = toolCall.function.name;
    const toolCallId = toolCall.id;

    if (isVerbose()) {
      agentIO.verbose('tool', `Executing (parallel): ${toolName}`);
    }

    const promise = (async () => {
      try {
        const output = await ctx.core.escAware(
          async (abortController) => {
            return await loader.execute(
              toolName, ctx,
              toolCall.function.arguments as Record<string, unknown>,
              abortController.signal,
            );
          },
          () => 'Tool interrupted by user.',
        );
        return { output, error: undefined };
      } catch (err) {
        return { output: '', error: err instanceof Error ? err : new Error(String(err)) };
      }
    })();

    executionMap.set(toolCallId, promise);
  }

  // 2. Wait for all executions to complete (or be interrupted by ESC)
  const resultEntries = await Promise.all(
    [...executionMap.entries()].map(async ([id, p]) => [id, await p] as const)
  );
  const results = new Map(resultEntries);

  // 3. Process results SEQUENTIALLY in original tool call order
  for (const toolCall of hookResult.calls) {
    const toolCallId = toolCall.id;
    const toolName = toolCall.function.name;

    // Blocked call: register block message (same as sequential)
    if (hookResult.blockedCalls.has(toolCallId)) {
      triologue.tool(toolName, hookResult.blockedCalls.get(toolCallId)!, toolCallId);
      continue;
    }

    const { output, error } = results.get(toolCallId)!;

    // Error handling (same as sequential path)
    if (error) {
      if (error instanceof ResultTooLargeError) {
        const truncatedOutput = /* same as current */;
        triologue.tool(toolName, truncatedOutput, toolCallId);
        loopEvents.emit('tool_error', { tool: toolName, error: error.message, kind: 'result_too_large' });
        ctx.core.increaseConfusionIndex(2);
      } else {
        const errorMsg = error.message;
        triologue.tool(toolName, `Error: ${errorMsg}`, toolCallId);
        agentIO.brief('error', 'tool', `${toolName} failed: ${errorMsg}`);
        loopEvents.emit('tool_error', { tool: toolName, error: errorMsg, kind: 'generic' });
        ctx.core.increaseConfusionIndex(2);
      }
      continue;
    }

    // Success: register result and post-process (same as sequential)
    if (isVerbose()) {
      agentIO.verbose('tool', `Result: ${toolName}`, { outputLength: output.length });
    }
    loopEvents.emit('tool_executed', { tool: toolName, outputLength: output.length });

    sequence.add({ tool: toolName, args: toolCall.function.arguments, result: output, timestamp: Date.now() });
    triologue.tool(toolName, output, toolCallId);
    await env.requestEmbeddingTracker.addEntry(toolName, toolCall.function.arguments);
    // ... confusion index, EXPLORATION_TOOLS check, brief special case ...

    // Check ESC: if pressed during parallel execution, register remaining
    // results (already collected) then break to return STOP
    if (agentIO.isNeglectedMode()) {
      // Register any remaining blocked/executed results, then return STOP
      // (all results are already in the `results` map, so we continue the
      // loop to register them, then check ESC after the loop)
      // Actually — since all results are already computed, we register ALL
      // of them in order regardless of ESC. The ESC check happens AFTER
      // the loop.
      continue;
    }
  }

  // 4. After all results registered, check ESC
  if (agentIO.isNeglectedMode()) {
    loopEvents.emit('esc_interrupt', { state: 'tool' });
    // No skipPendingTools needed — all tools have results registered
    return AgentState.STOP;
  }

  // 5. Inject deferred hook messages (same as current)
  for (const dm of hookResult.deferredMessages) {
    triologue.note('REMINDER', dm.message, dm.hookName);
  }

  return AgentState.COLLECT;
}
```

**Key design decisions in the parallel path:**
- All tool results are registered in the original tool call order (preserves TP constraint, sequence order, embedding order)
- `addEntry` + `getMaxSimilarity` are awaited sequentially in the post-processing loop (preserves semantic duplication detection order)
- ESC during parallel execution: all tools get results (mix of normal/interrupted), all registered, then return STOP — no `skipPendingTools` needed
- The `brief` tool is NOT in `PARALLEL_SAFE_TOOLS`, so its special post-processing never runs in the parallel path

