```ts
/**
 * Summarize messages into a single pair using LLM.
 *
 * Messages are minified to compact text, then split at `ux|` (user-turn)
 * boundaries into self-contained chunks. Each chunk is summarized
 * independently; chunk summaries are concatenated into the final pair.
 *
 * Chunking at ux boundaries ensures no chunk starts with an orphaned
 * tool result (to|) or tool call (ti|) — every chunk begins with the
 * user's request that prompted the following assistant/tools exchange.
 * Child narratives (ux|[name summary]...) and their ready-notes
 * (ux|[MAIL] [READY]...) are both ux-prefixed, so the splitter keeps
 * each as the start of a new chunk, preserving their semantic pairing.
 *
 * Token estimation operates on the already-minified text, so the
 * chunker sees exactly what the LLM will receive — no overflow risk.
 */
async function summarizeMessages(messages: Message[]): Promise<SummaryPair> {
  if (messages.length === 0) {
    return [
      { role: 'user', content: '[Empty conversation]' },
      { role: 'assistant', content: 'Understood.' },
    ];
  }

  const fullText = messagesToText(messages);
  const SUMMARY_PROMPT_PREFIX =
    `Summarize this conversation for continuity. Include:\n` +
    `1) What was discussed or accomplished\n` +
    `2) Key decisions or findings\n` +
    `3) Current state and next steps\n\n` +
    `Be concise but preserve critical details.\n\n`;

  // If the entire conversation fits in one chunk, summarize directly.
  const totalTokens = estimateTextTokens(fullText);
  if (totalTokens <= getTokenThreshold()) {
    const response = await retryChat({
      model: MODEL,
      messages: [{ role: 'user', content: `${SUMMARY_PROMPT_PREFIX}${fullText}` }],
    });
    const summary = response.message.content || '(no summary)';
    return [
      { role: 'user', content: `[Context from previous conversation]\n\n${summary}` },
      { role: 'assistant', content: 'Understood. I have the context from the summary.' },
    ];
  }

  // Split into ux-delimited chunks. Each chunk starts at a `ux|` line and
  // extends to the next `ux|` line (exclusive). The 2-line header
  // (> ux = user...) is prepended to the first chunk only.
  const lines = fullText.split('\n');
  const headerLines = lines.filter(l => l.startsWith('>'));
  const bodyLines = lines.filter(l => !l.startsWith('>'));

  const chunks: string[] = [];
  let current: string[] = [];
  let currentTokens = 0;
  const headerStr = headerLines.join('\n') + '\n';

  for (const line of bodyLines) {
    const lineTokens = estimateTextTokens(line);
    // Start a new chunk at ux| boundary IF the current chunk is non-empty
    // AND adding this line would exceed the threshold. This keeps each
    // chunk under the token limit while ensuring every chunk starts with ux|.
    if (line.startsWith('ux|') && current.length > 0 &&
        currentTokens + lineTokens > getTokenThreshold()) {
      chunks.push(current.join('\n'));
      current = [line];
      currentTokens = lineTokens;
    } else {
      current.push(line);
      currentTokens += lineTokens;
    }
  }
  if (current.length > 0) chunks.push(current.join('\n'));

  // Summarize each chunk, then concatenate summaries.
  const chunkSummaries: string[] = [];
  for (let i = 0; i < chunks.length; i++) {
    const chunkText = (i === 0 ? headerStr : '') + chunks[i];
    const response = await retryChat({
      model: MODEL,
      messages: [{ role: 'user', content: `${SUMMARY_PROMPT_PREFIX}${chunkText}` }],
    });
    chunkSummaries.push(response.message.content || '(no summary)');
  }

  // If multiple chunk summaries, do a final roll-up pass.
  let finalSummary: string;
  if (chunkSummaries.length === 1) {
    finalSummary = chunkSummaries[0];
  } else {
    const rolledText = chunkSummaries.map((s, i) => `### Part ${i + 1}\n${s}`).join('\n\n');
    const rollResponse = await retryChat({
      model: MODEL,
      messages: [{
        role: 'user',
        content:
          `Synthesize these partial summaries into one coherent summary. ` +
          `Preserve key decisions, findings, and next steps.\n\n${rolledText}`,
      }],
    });
    finalSummary = rollResponse.message.content || chunkSummaries.join('\n\n');
  }

  return [
    { role: 'user', content: `[Context from previous conversation]\n\n${finalSummary}` },
    { role: 'assistant', content: 'Understood. I have the context from the summary.' },
  ];
}
```

