/**
 * Iteratively summarize minified text with fold-forward.
 *
 * Splits the text at `ux|` boundaries into self-contained batches. Each
 * batch is summarized into a (ux, ax) pair; that pair's ux text is prepended
 * to the NEXT batch as prior context before summarizing. The final pair is
 * the accumulated result.
 *
 * Cutting at ux| ensures every batch starts with a user turn (the natural
 * conversational unit boundary) — no batch begins with an orphaned tool
 * result (to|) or tool call (ti|).
 */
async function summarizeMinifiedText(text: string): Promise<SummaryPair> {
  if (!text.trim()) {
    return [
      { role: 'user', content: '[Empty conversation]' },
      { role: 'assistant', content: 'Understood.' },
    ];
  }

  const totalTokens = estimateTextTokens(text);
  if (totalTokens <= getTokenThreshold()) {
    return summarizeTextChunk(text);
  }

  // Split at ux| boundaries. Keep the 2-line header for the first batch.
  const lines = text.split('\n');
  const headerLines = lines.filter(l => l.startsWith('>'));
  const bodyLines = lines.filter(l => !l.startsWith('>'));
  const headerStr = headerLines.join('\n');

  // Group body lines into batches at ux| boundaries, respecting token limit.
  const batches: string[] = [];
  let current: string[] = [];
  let currentTokens = 0;
  const threshold = getTokenThreshold();

  for (const line of bodyLines) {
    const lineTokens = estimateTextTokens(line);
    if (line.startsWith('ux|') && current.length > 0 &&
        currentTokens + lineTokens > threshold) {
      batches.push(current.join('\n'));
      current = [line];
      currentTokens = lineTokens;
    } else {
      current.push(line);
      currentTokens += lineTokens;
    }
  }
  if (current.length > 0) batches.push(current.join('\n'));

  // Iterative fold-forward: each batch's summary seeds the next batch.
  let priorPair: SummaryPair | undefined;
  for (let i = 0; i < batches.length; i++) {
    const batchText = (i === 0 ? headerStr + '\n' : '') + batches[i];
    const priorContext = priorPair ? priorPair[0].content : undefined;
    priorPair = await summarizeTextChunk(batchText, priorContext);
  }

  return priorPair!;
}
```

