  //    Keyed by triologuePath for lookup during the text walk.
  const childSummaryTextByPath = new Map<string, string>();
  for (const ev of readyEvents) {
    const pair = await summarizeChildByPath(ev.name, ev.triologuePath);
    // pair[0].content is "[name summary]\n<summary text>" — already a
    // self-contained narrative. We insert it as a ux| line in the lead text.
    childSummaryTextByPath.set(ev.triologuePath, pair[0].content);
  }

  // 2. Minify the full lead triologue to text
  const leadMinified = messagesToText(messages);

  // 3. Walk lead minified lines; at [READY] marker lines, insert the child
  //    summary text BEFORE the marker. Only lines starting with `ux|` can be
  //    [MAIL] notes containing [READY] — tool results (to|) or assistant
  //    text (ax|) that happen to contain the literal are skipped.
  const leadLines = leadMinified.split('\n');
  const wovenLines: string[] = [];
  for (const line of leadLines) {
    if (line.startsWith('ux|')) {
      const pathMatch = line.match(READY_PATH_REGEX);
      if (pathMatch) {
        const p = pathMatch[1].trim();
        const summaryText = childSummaryTextByPath.get(p);
        if (summaryText) {
          // Insert child summary as a ux| line before the [READY] note.
          wovenLines.push(`ux|${summaryText}`);
        }
      }
    }
    wovenLines.push(line);
  }

  // 4. Iteratively summarize the woven text with fold-forward
  return summarizeMinifiedText(wovenLines.join('\n'));
}
