**Daemon 初始化块** — 插入在 `--auto` 块（~line 333）之后：

```typescript
// ── --daemon CLI arg: headless daemon mode ──
if (shouldDaemon()) {
  // Force auto mode on (daemon is always headless auto)
  autoState.resetStreak();
  autoState.setAuto(true);
  console.log(chalk.cyan('daemon mode is on (--daemon). Running headless.'));

  const daemonSkill = getDaemonSkill();

  // Dedup check: scan identity.json for existing fresh instance
  // with same role (skill name or 'daemon') + workDir
  const identities = ctx.peer.listIdentities();
  const selfWorkDir = process.cwd();
  const roleLabel = daemonSkill || 'daemon';
  for (const entry of identities) {
    if (entry.role === roleLabel && entry.workDir === selfWorkDir) {
      if (ctx.peer.isFresh(entry.sessionId)) {
        console.error(chalk.red(`A daemon instance with role '${roleLabel}' is already running for this workDir.`));
        console.error(chalk.gray(`Existing session: ${entry.sessionId.slice(0, 7)}`));
        ctx.peer.stop();
        process.send!({ type: 'exit' });
        process.exit(1);
      }
    }
  }

  // Auto-load skill if provided
  if (daemonSkill) {
    const skill = loader.getSkill(daemonSkill);
    if (!skill) {
      console.error(chalk.red(`Skill '${daemonSkill}' not found. Cannot start daemon.`));
      ctx.peer.stop();
      process.send!({ type: 'exit' });
      process.exit(1);
    }
    // Inject skill load as a note so the LLM processes it on first turn
    triologue.note('SYSTEM', `Daemon started with skill '${daemonSkill}'. Load it via skill_load(name="${daemonSkill}").`);
  }

  // Start cron timer if skill has service_cron
  if (daemonSkill) {
    const skill = loader.getSkill(daemonSkill);
    if (skill?.service_cron) {
      const cronJob = new Cron(skill.service_cron, () => {
        const title = 'Service nudge';
        const content = `[Service nudge] Cron tick for '${daemonSkill}'. Check for pending work and process it.`;
        ctx.mail.appendMail('lead', title, content);
        console.log(chalk.gray(`[cron] Nudge sent for '${daemonSkill}'`));
      });
      // Store for cleanup
      (ctx as any)._daemonCronJob = cronJob;
      console.log(chalk.gray(`[cron] Started: ${skill.service_cron}`));
    }
  }
}
```

