### 2.6 `src/index.ts` — Coordinator detach 逻辑

**`startLead()` 函数（~line 154）之前**，新增 daemon 检测 + detach 分支：

在 `runCoordinator()` 顶部（~line 96，`loadEnv()` 之后），添加 daemon 检测：

```typescript
// ── --daemon: detach and exit immediately ──
// When --daemon is set, spawn the Lead as a detached background process
// and exit the Coordinator immediately. No terminal, no stdin forwarding.
if (shouldDaemon()) {
  const tsxScript = resolve(PROJECT_ROOT, 'src', 'lead.ts');
  const forwardedArgs = [...process.argv.slice(2)];
  if (skipHealthCheck) forwardedArgs.push('--skip-healthcheck');

  const env = { ...process.env };
  env.COLUMNS = '120';
  env.MYCC_COORDINATOR_PID = String(process.pid);

  const child = spawnTsx({
    script: tsxScript,
    args: forwardedArgs,
    cwd: process.cwd(),
    stdio: 'ignore',           // no terminal I/O
    env,
    detached: process.platform !== 'win32',  // detached on Unix; windowsHide on Windows
  });

  if (process.platform === 'win32') {
    // windowsHide is set by spawnTsx internally; just unref
  }

  child.unref();
  console.log(chalk.green(`Daemon started (pid: ${child.pid}).`));
  process.exit(0);
}
```

需要从 `config.js` 导入 `shouldDaemon`：

```typescript
import { ..., shouldDaemon, ... } from './config.js';
```

**注意：** `spawnTsx` 的 `detached: true` 在 Unix 上创建新进程组；`stdio: 'ignore'` 断开所有 stdio 管道；`child.unref()` 让父进程可以退出。Windows 上 `detached` 行为不同（需要 `windowsHide: true`），需确认 `spawnTsx` 是否已支持此选项。

