import { getShellInfo } from '../utils/shell-detect.js';

function shellNameFor(kind: string): string {
  switch (kind) {
    case 'pwsh7': return 'pwsh';
    case 'powershell5': return 'powershell';
    case 'bash': return 'bash';
    case 'zsh': return 'zsh';
    default: throw new Error(`hand_over: unsupported shell '${kind}'`);
  }
}

function spawnTmux(args: string[], cwd: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const p = spawn('tmux', args, { cwd, stdio: 'ignore' });
    p.on('error', reject);
    p.on('close', (code) =>
      code === 0 ? resolve() : reject(new Error(`tmux exited ${code}`))
    );
  });
}
