### `grid` op 实现细节（evaluator.js 新增分支）

```js
} else if (opName === 'grid') {
  if (!Array.isArray(values)) throw new Error('values must be a 2D array');
  const a = parseArea2D(area, maxRow);  // row-major cells
  // 计算区块的行列数
  const [startCell, endCell] = area.split(':');
  const s = parseCellId(startCell), e = parseCellId(endCell);
  const cols = e.col - s.col + 1;
  const rows = e.row - s.row + 1;
  // values 是 rows×cols 的二维数组
  if (values.length !== rows) throw new Error(`grid: expected ${rows} rows, got ${values.length}`);
  let idx = 0;
  for (let r = 0; r < rows; r++) {
    const row = values[r];
    if (!Array.isArray(row) || row.length !== cols)
      throw new Error(`grid row ${r}: expected ${cols} cols, got ${row?.length}`);
    for (let c = 0; c < cols; c++) {
      const v = row[c];
      if (v === null || v === undefined) { idx++; continue; }  // 跳过
      const cell = a.cells[idx];
      if (typeof v === 'number') grid.set(cell, { type: 'num', value: v });
      else if (typeof v === 'string') grid.set(cell, { type: 'text', value: v });
      else throw new Error(`grid cell ${cell}: value is ${typeof v} (expected number/string/null)`);
      idx++;
    }
  }
}
```

