### 7. **New file**: `src/context/parent/sim-tool.ts` — Mini-loop simulation

The core simulation function. A bounded mini-loop that gives the LLM access to all real tools and instructs it to simulate the sim-tool's result:

```typescript
/**
 * sim-tool.ts - Simulated tool execution via a bounded LLM mini-loop.
 *
 * When a teammate calls a sim-tool (definition only, no handler), the lead
 * runs this mini-loop to produce the result. The LLM has access to all real
 * tools (web_fetch, bash, read_file, etc.) and decides how to simulate the
 * requested tool. The loop is bounded (MAX_ITERATIONS) to prevent infinite
 * tool-call chains.
 */

import { loader } from '../shared/loader.js';
import { retryChat, MODEL } from '../../engine/chat-provider.js';
import type { AgentContext, Message, Tool, ToolCall } from '../../types.js';

const MAX_ITERATIONS = 5;

/**
 * Simulate a tool call using a bounded mini-loop.
 *
 * @param ctx - Lead's AgentContext (for executing real tools)
 * @param toolName - The sim-tool's name
 * @param toolDescription - The sim-tool's description
 * @param args - The arguments the teammate passed
 * @returns The simulated tool result as a string
 */
export async function simulateToolCall(
  ctx: AgentContext,
  toolName: string,
  toolDescription: string,
  args: Record<string, unknown>,
): Promise<string> {
  const tools = loader.getToolsForScope('main');
  const argsJson = JSON.stringify(args, null, 2);

  const systemPrompt = `You are simulating a tool call for a teammate agent. ` +
    `The teammate called a tool named "${toolName}" with the following description:\n\n` +
    `${toolDescription}\n\n` +
    `The teammate passed these arguments:\n${argsJson}\n\n` +
    `Use the available tools (web_fetch, bash, read_file, etc.) to produce a realistic ` +
    `result for this tool. After gathering information, return ONLY the tool result ` +
    `as plain text — no explanations, no meta-commentary. The output will be returned ` +
    `directly to the teammate as the tool result.`;

  let messages: Message[] = [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: `Simulate the "${toolName}" tool call with args: ${argsJson}` },
  ];

  for (let i = 0; i < MAX_ITERATIONS; i++) {
    const response = await retryChat(
      { model: MODEL, messages, tools },
      { noSpinner: true },
    );

    const toolCalls = response.message.tool_calls as ToolCall[] | undefined;

    if (!toolCalls || toolCalls.length === 0) {
      // Text-only response = the simulation result
      return response.message.content || '';
    }

    // Register assistant message with tool calls
    messages.push({
      role: 'assistant',
      content: response.message.content || '',
      tool_calls: toolCalls,
    });

    // Execute each tool call using the lead's real tools
    for (const tc of toolCalls) {
      const realToolName = tc.function.name;
      const realToolArgs = tc.function.arguments as Record<string, unknown>;
      const output = await loader.execute(realToolName, ctx, realToolArgs);
      messages.push({
        role: 'tool',
        content: output,
        tool_name: realToolName,
        tool_call_id: tc.id,
      });
    }
  }

  // Exceeded max iterations — return last assistant content or fallback
  const lastAssistant = messages.filter(m => m.role === 'assistant').pop();
  return lastAssistant?.content || `Error: simulation exceeded ${MAX_ITERATIONS} iterations without producing a result.`;
}
```

